	typedef CConstTextPtr						const_iterator;	typedef std::reverse_iterator<iterator>			reverse_iterator;	typedef std::reverse_iterator<const_iterator>	const_reverse_iterator;	//------------------------------------------------------------------------------------	// Construction and destruction	//------------------------------------------------------------------------------------	CConstTextPtr();	CConstTextPtr(const CTextBuffer* theBuffer);	CConstTextPtr(const CTextBuffer* theBuffer, size_t offset);		// Constructor	CConstTextPtr(const CConstTextPtr& rhs);		// Copy constructor	~CConstTextPtr() {}	//------------------------------------------------------------------------------------	// Comparison	//------------------------------------------------------------------------------------	bool operator ==(const CConstTextPtr& rhs) const;		// equality for a CConstTextPtr	bool operator ==(const void* ptr) const;		// equality for a void*	bool operator !=(const CConstTextPtr& rhs) const;		// inequality for a CConstTextPtr	bool operator !=(const void* ptr) const;		// inequality for a void*		bool operator >(const CConstTextPtr& rhs) const;	bool operator >=(const CConstTextPtr& rhs) const;	bool operator <(const CConstTextPtr& rhs) const;	bool operator <=(const CConstTextPtr& rhs) const;	//------------------------------------------------------------------------------------	// Pointer arithmetic	//	// The pointer arithmetic methods simply modify the offset. They don't do any range	// checking so the pointer is allowed to be out of range as long as it isn't used	// to access data. 	//------------------------------------------------------------------------------------	CConstTextPtr& operator++();		// prefix increment	CConstTextPtr operator++(int);		// postfix increment	CConstTextPtr& operator+=(difference_type increment);		// increment assignment	CConstTextPtr operator+(difference_type increment) const;		// addition of integer	CConstTextPtr& operator--();		// prefix decrement	CConstTextPtr operator--(int);		// postfix decrement		CConstTextPtr& operator-=(difference_type decrement);		// decrement assignment	CConstTextPtr operator-(difference_type decrement) const;		// subtraction of integer		difference_type operator-(const CConstTextPtr& rhs) const;		// distance between	//------------------------------------------------------------------------------------	// Data Access	//	// All the data access methods will throw if there is no buffer or if the offset is 	// out of range. They may wait on the buffer for data to become available. 	//------------------------------------------------------------------------------------	CConstTextPtr& operator=(const CConstTextPtr& rhs);		// assignment	CConstTextPtr& operator=(const charT* ptr);		// assignment to nil	//void operator>>(char in);	//	// input operator	charT operator*() const;		// indirection	operator const charT*() const;		// conversion	const charT& operator[](difference_type index) const;		// subscripting		bool AtEnd() const;		// Is the offset at the end of the buffer	difference_type length() const;		// How big is the buffer from the offset	difference_type GetOffset() const;		// Where is the offset pointer	size_type size() const;		// How big is the buffer. This is the whole buffer, not just the part		// after our offset. 	bool empty() const	{		return length() == 0;	}	bool IsBufferComplete() const;		// Do we have all of the data.//	void Place(const char in, difference_type index = 0);//		// place a character into the buffer	bool AssureData(difference_type assure = 0) const;		// Make sure there are at least assure bytes of data in the buffer after		// the current offset. 	const charT* get(difference_type assure) const;		// Lock the data buffer assuring assure bytes. 		// Will throw if the data is not there. 	const charT* get() const;		// Ptr address. Will throw if the buffer is not there. protected:	const charT* addr() const;		// Ptr address for comparison only (not range checked)		//------------------------------------------------------------------------------------	// Debugging Aids	//------------------------------------------------------------------------------------#if qDebug		char*	SetCharPtr();#endif	//------------------------------------------------------------------------------------	// Data	//------------------------------------------------------------------------------------protected:	const CTextBuffer*	fBuffer;	difference_type		fOffset;	//long				fSize;	//long				fLockCount;#if qDebug		charT*				fCharPtr;		// A pointer to (fbuffer)+fOffset#endif};//========================================================================================// class CTextPtr//========================================================================================class CTextPtr : public CConstTextPtr{public:	//------------------------------------------------------------------------------------	// Types	//------------------------------------------------------------------------------------	typedef CTextPtr							iterator;	typedef std::reverse_iterator<iterator>		reverse_iterator;	//------------------------------------------------------------------------------------	// Construction and destruction	//------------------------------------------------------------------------------------	CTextPtr();	CTextPtr(CTextBuffer* theBuffer);	CTextPtr(CTextBuffer* theBuffer, size_t offset);		// Constructor	CTextPtr(const CTextPtr& rhs);		// Copy constructor	~CTextPtr() {}	//------------------------------------------------------------------------------------	// Pointer arithmetic	//	// The pointer arithmetic methods simply modify the offset. They don't do any range	// checking so the pointer is allowed to be out of range as long as it isn't used	// to access data. 	//------------------------------------------------------------------------------------	CTextPtr& operator++();		// prefix increment	CTextPtr operator++(int);		// postfix increment	CTextPtr& operator+=(difference_type increment);		// increment assignment	CTextPtr operator+(difference_type increment) const;		// addition of integer	CTextPtr& operator--();		// prefix decrement	CTextPtr operator--(int);		// postfix decrement		CTextPtr& operator-=(difference_type decrement);		// decrement assignment	CTextPtr operator-(difference_type decrement) const;		// subtraction of integer		difference_type operator-(const CConstTextPtr& rhs) const;		// distance between	//------------------------------------------------------------------------------------	// Data Access	//	// All the data access methods will throw if there is no buffer or if the offset is 	// out of range. They may wait on the buffer for data to become available. 	//------------------------------------------------------------------------------------	CTextPtr& operator=(const CTextPtr& rhs);		// assignment	CTextPtr& operator=(const charT* ptr);		// assignment to nil	charT operator*() const;		// indirection	operator charT*();	operator const charT*() const;		// conversion	charT& operator[](difference_type index);	const charT& operator[](difference_type index) const;		// subscripting		charT* get(difference_type assure);	const charT* get(difference_type assure) const;		// Lock the data buffer assuring assure bytes. 		// Will throw if the data is not there. 	charT* get();	const charT* get() const;		// Ptr address. Will throw if the buffer is not there. };//========================================================================================// Global Functions//========================================================================================// ANSI String Library Equivalentsint					strncmp(const char* str1, const CTextPtr& str2, size_t len);int					strncmp(const CTextPtr& str1, const char* str2, size_t len);CTextPtr			strstr(const CTextPtr& str, const char* pat);CTextPtr			FindToken(const CTextPtr&, const char* tokens);CTextPtr			FindNoSpacePrintASCIIToken(const CTextPtr& string);void				MakeUpperCase(const CTextPtr& chars, long length);CTextPtr			ParseSymbol(const CTextPtr& parse, CTextPtr& symbol, long& length);CTextPtr			ParseValue(const CTextPtr& parse, CTextPtr& value, long* length, const char* except = nil);#endif // __CTextPtr__